<?php
declare(strict_types=1);
namespace NL;
function sanitise_collection(string $key,array $value):array {
 if(count($value)>300)throw new \InvalidArgumentException('Слишком много элементов.');$out=[];$ids=[];
 $fields=match($key){'gallery'=>['caption'],'recognition'=>['title','description'],'documents'=>['title','description','group','registered','expires'],default=>throw new \InvalidArgumentException('Неизвестный раздел.')};
 $urls=match($key){'gallery'=>['photo','thumbnail','source_url'],'recognition'=>['photo','pdf'],'documents'=>['pdf']};
 foreach($value as $item){$id=(string)($item['id']??'');if(!preg_match('/^[a-z0-9][a-z0-9-]{0,70}$/',$id)||isset($ids[$id]))throw new \InvalidArgumentException('Элементы должны иметь разные идентификаторы.');$ids[$id]=true;$row=['id'=>$id];foreach($fields as $field)$row[$field]=mb_substr(trim((string)($item[$field]??'')),0,5000);foreach($urls as $field)$row[$field]=url((string)($item[$field]??''),true);
 if($key==='gallery'&&$row['photo']==='')throw new \InvalidArgumentException('Выберите фотографию.');if($key==='gallery'&&!$row['thumbnail'])$row['thumbnail']=$row['photo'];
 if($key==='recognition'){$row['kind']=in_array($item['kind']??'',['featured','thanks','membership'],true)?$item['kind']:'thanks';if(!$row['photo']||!$row['pdf'])throw new \InvalidArgumentException('Выберите изображение и PDF документа.');}
 if($key==='documents'&&(!$row['title']||!$row['pdf']))throw new \InvalidArgumentException('Укажите название и PDF документа.');$out[]=$row;
 }return $out;
}
function collection_image(array $p,string $alt):string {return '<a class="recognition-image" href="'.e($p['photo']).'" target="_blank" rel="noopener noreferrer" aria-label="Увеличить: '.e($alt).'"><img src="'.e($p['photo']).'" alt="'.e($alt).'" loading="lazy"></a>';}
function collection_pdf(array $p):string {return '<a class="text-link" href="'.e($p['pdf']).'" target="_blank" rel="noopener noreferrer">Открыть PDF ↗</a>';}
function render_collections(\DOMDocument $d,\DOMXPath $xp):void {
 $replace=function(string $query,string $html)use($d,$xp){$node=$xp->query($query)->item(0);if(!$node)return;[$source,$other]=dom($html);$root=$other->query('//*[@id="cms-root"]')->item(0);foreach(iterator_to_array($root->childNodes) as $child)$node->parentNode->insertBefore($d->importNode($child,true),$node);$node->parentNode->removeChild($node);};
 if($xp->query('//*[contains(concat(" ",normalize-space(@class)," ")," album-grid ")]')->length){$photos=doc('gallery')['value'];$html='';foreach($photos as $i=>$p){$html.='<figure><a class="gallery-picture" href="'.e($p['photo']).'" data-gallery-photo data-original="'.e($p['source_url']).'" aria-label="Открыть фото '.($i+1).'"><img src="'.e($p['thumbnail']?:$p['photo']).'" alt="'.e($p['caption']).'" loading="lazy"><span class="gallery-zoom" aria-hidden="true">↗</span></a><figcaption>'.e($p['caption']).'</figcaption></figure>';}$grid=$xp->query('//*[contains(concat(" ",normalize-space(@class)," ")," album-grid ")]')->item(0);replace_inner($grid,$html);$grid->setAttribute('aria-label','Фотографии компании');}
 if($xp->query('//*[@id="thanks"]|//*[contains(concat(" ",normalize-space(@class)," ")," thanks-teaser ")]')->length){$items=doc('recognition')['value'];$featured=array_values(array_filter($items,fn($p)=>$p['kind']==='featured'));$ordinary=array_values(array_filter($items,fn($p)=>$p['kind']==='thanks'));$members=array_values(array_filter($items,fn($p)=>$p['kind']==='membership'));
 $html='';foreach($featured as $p)$html.='<article class="featured-thanks"><div><p class="eyebrow">От участников СВО</p><h3>'.e($p['title']).'</h3>'.($p['description']?'<p>'.e($p['description']).'</p>':'').collection_pdf($p).'</div>'.collection_image($p,'Благодарность от участников СВО').'</article>';
 $replace('//*[contains(concat(" ",normalize-space(@class)," ")," featured-thanks ")]',$html);
 $html='';foreach($ordinary as $p)$html.='<figure class="recognition-card">'.collection_image($p,$p['title']?:'Благодарственное письмо').'<figcaption>'.($p['title']?'<h3>'.e($p['title']).'</h3>':'').($p['description']?'<p>'.e($p['description']).'</p>':'').collection_pdf($p).'</figcaption></figure>';$grid=$xp->query('//*[contains(concat(" ",normalize-space(@class)," ")," recognition-grid ")]')->item(0);if($grid)replace_inner($grid,$html);
 $html='';foreach($members as $p)$html.='<article class="membership-card" id="membership">'.collection_image($p,'Членский билет').'<div><p class="eyebrow">Членский билет</p><h3>'.e($p['title']).'</h3><p>'.e($p['description']).'</p>'.collection_pdf($p).'</div></article>';$replace('//*[contains(concat(" ",normalize-space(@class)," ")," membership-card ")]',$html);
 $teaser=$xp->query('//*[contains(concat(" ",normalize-space(@class)," ")," thanks-teaser ")]')->item(0);if($teaser){$image=$xp->query('.//a[contains(concat(" ",normalize-space(@class)," ")," recognition-image ")]',$teaser)->item(0);if($image&&$featured){[$source,$other]=dom(collection_image($featured[0],'Благодарность от участников СВО'));$image->parentNode->replaceChild($d->importNode($other->query('//*[@id="cms-root"]/*')->item(0),true),$image);}elseif(!$featured)$teaser->parentNode->removeChild($teaser);}
 }
 $list=$xp->query('//*[contains(concat(" ",normalize-space(@class)," ")," document-list ")]')->item(0);if($list){$items=doc('documents')['value'];$html='';foreach($items as $i=>$p)$html.='<article class="document-card"><div class="document-symbol">PDF<span>'.str_pad((string)($i+1),2,'0',STR_PAD_LEFT).'</span></div><div><p class="eyebrow">'.e($p['group']).'</p><h2>'.e($p['title']).'</h2><p>'.e($p['description']).'</p><dl><dt>Дата регистрации</dt><dd>'.e($p['registered']).'</dd><dt>Окончание срока по документу</dt><dd>'.e($p['expires']).'</dd></dl><a class="button outline" href="'.e($p['pdf']).'" target="_blank" rel="noopener noreferrer">Открыть PDF ↗</a></div></article>';replace_inner($list,$html);}
}
